{
  "action_id": "update_w1_init",
  "kind": "UPDATE",
  "source_id": "conv_b5e6f3d3bab9",
  "purpose": "建立可复用脱敏工作流 W（结构盘点→按“前2+***+后2”打码→残留校验），把用户第二轮纠正的命名规则固化为需求，并登记 openpyxl 缺失这一真实阻塞疑点。",
  "arguments": {
    "graph": {
      "base_version": 1,
      "nodes": [
        {
          "id": "req_desensitize_v1",
          "type": "requirement",
          "source_ids": ["conv_b5e6f3d3bab9"],
          "evidence_refs": [
            {"source_id": "conv_b5e6f3d3bab9", "turn_index": 0, "role": "user", "quote": "帮我把这份表格做一下脱敏处理"}
          ],
          "status": "proposed"
        },
        {
          "id": "req_mask_rule_v1",
          "type": "requirement",
          "source_ids": ["conv_b5e6f3d3bab9"],
          "evidence_refs": [
            {"source_id": "conv_b5e6f3d3bab9", "turn_index": 1, "role": "user", "quote": "只留前两个字和后两个字，中间用***替代"}
          ],
          "status": "proposed"
        },
        {
          "id": "proc_mask_v1",
          "type": "procedure",
          "source_ids": ["conv_b5e6f3d3bab9"],
          "evidence_refs": [
            {"source_id": "conv_b5e6f3d3bab9", "turn_index": 1, "role": "user", "quote": "只留前两个字和后两个字，中间用***替代"}
          ],
          "status": "proposed"
        }
      ],
      "edges": [
        {
          "from": "req_desensitize_v1",
          "to": "proc_mask_v1",
          "type": "supports",
          "status": "proposed",
          "evidence_refs": [
            {"source_id": "conv_b5e6f3d3bab9", "turn_index": 0, "role": "user", "quote": "帮我把这份表格做一下脱敏处理"}
          ]
        },
        {
          "from": "req_mask_rule_v1",
          "to": "proc_mask_v1",
          "type": "supports",
          "status": "proposed",
          "evidence_refs": [
            {"source_id": "conv_b5e6f3d3bab9", "turn_index": 1, "role": "user", "quote": "只留前两个字和后两个字，中间用***替代"}
          ]
        }
      ]
    },
    "workflows": [
      {
        "spec": {
          "id": "conv_b5e6f3d3bab9_w1",
          "task": "对含多个 sheet 的业务表格做脱敏：按用户规则把客户/单位名称改为“前两字+***+后两字”，删除括号内联系人备注，销售对接人编号化，隐藏电话/地址等个人信息，保留金额、产品、时间等业务数据，并输出脱敏版与内部对照表。",
          "parameters": {
            "input_path": "未来用户提供的待脱敏表格路径（xlsx）",
            "output_path": "脱敏版输出路径",
            "mapping_path": "内部对照表输出路径",
            "name_columns": "需按前2后2打码的实体名称列（按表头定位，不写死列号）",
            "sales_columns": "销售对接人列",
            "free_text_columns": "可能内嵌姓名/电话/地址的备注列"
          },
          "requirements": [
            {
              "text": "对表格做脱敏处理",
              "evidence_refs": [
                {"source_id": "conv_b5e6f3d3bab9", "turn_index": 0, "role": "user", "quote": "帮我把这份表格做一下脱敏处理"}
              ]
            },
            {
              "text": "名称脱敏规则：只留前两个字和后两个字，中间用***替代",
              "evidence_refs": [
                {"source_id": "conv_b5e6f3d3bab9", "turn_index": 1, "role": "user", "quote": "只留前两个字和后两个字，中间用***替代"}
              ]
            }
          ],
          "conditions": [
            "名称长度不足以同时保留前2后2（含2字以内、或前后重叠）时，整体打码为***，避免等于未脱敏",
            "不同原始名称打码后撞名时，追加 (2)(3)… 后缀区分，保证可追溯"
          ],
          "preserved_state": [
            "金额、产品信息、费用类型、时间节点、订单状态、行业方向、应用场景、预估容量等业务数据保持不变",
            "原表列宽与样式尽量保留"
          ],
          "steps": [
            {
              "id": "s1",
              "purpose": "盘点真实表结构并定位敏感列",
              "input_refs": ["input_path"],
              "preconditions": ["input_path 指向可读的 xlsx"],
              "operation": "读取工作簿，列出每个 sheet 的名称、行列范围与表头，按表头语义定位名称列、销售对接人列、备注列、电话/地址列，输出结构清单供后续步骤引用",
              "output_refs": ["structure_report"],
              "postconditions": ["每个 sheet 的敏感列位置已明确，不依赖历史会话中的列号描述"],
              "asset_ids": [],
              "evidence_refs": [
                {"source_id": "conv_b5e6f3d3bab9", "turn_index": 0, "role": "user", "quote": "帮我把这份表格做一下脱敏处理"}
              ],
              "support_status": "proposed"
            },
            {
              "id": "s2",
              "purpose": "按规则生成脱敏数据与对照表",
              "input_refs": ["input_path", "structure_report"],
              "preconditions": ["s1 已定位敏感列"],
              "operation": "对名称列执行“前2+***+后2”（短名/重叠整体***，撞名加后缀）；删除括号内联系人备注；销售对接人编号化；电话/地址替换为占位符；业务列原样保留；同时写出打码名↔原始名对照表",
              "output_refs": ["output_path", "mapping_path"],
              "postconditions": ["脱敏文件与对照表均已生成"],
              "asset_ids": [],
              "evidence_refs": [
                {"source_id": "conv_b5e6f3d3bab9", "turn_index": 1, "role": "user", "quote": "只留前两个字和后两个字，中间用***替代"}
              ],
              "support_status": "proposed"
            },
            {
              "id": "s3",
              "purpose": "残留校验并交付",
              "input_refs": ["output_path", "mapping_path"],
              "preconditions": ["s2 已产出文件"],
              "operation": "扫描脱敏文件全部单元格，检查是否仍含原始客户名、销售姓名、手机号、地址关键词；统计残留数，为 0 才判定可交付，否则回到 s2 修复",
              "output_refs": ["residual_report"],
              "postconditions": ["残留计数与结论已记录"],
              "asset_ids": [],
              "evidence_refs": [
                {"source_id": "conv_b5e6f3d3bab9", "turn_index": 1, "role": "user", "quote": "只留前两个字和后两个字，中间用***替代"}
              ],
              "support_status": "proposed"
            }
          ],
          "control_flow": {
            "dependencies": [["s1", "s2"], ["s2", "s3"]],
            "branches": [],
            "repair_loops": [
              {
                "from": "s3",
                "to": "s2",
                "max_iterations": 2,
                "exit_condition": "残留计数为 0 则通过；否则最多再修一轮，仍非 0 则报告剩余残留并停止"
              }
            ]
          },
          "failure_handling": [
            "缺少 xlsx 读写库时，改用 zipfile+ElementTree 直接读写 xlsx 内部 XML，或明确报告环境阻塞",
            "列定位失败（表头不匹配）时停止并报告，不猜测列号"
          ],
          "checks": [
            "输出文件存在且可被解析",
            "脱敏后名称符合“前2+***+后2”，短名整体为***",
            "脱敏文件中原始客户名/销售姓名/电话/地址残留计数为 0",
            "对照表包含打码名↔原始名映射"
          ],
          "asset_refs": [],
          "evidence_refs": [
            {"source_id": "conv_b5e6f3d3bab9", "turn_index": 0, "role": "user", "quote": "帮我把这份表格做一下脱敏处理"},
            {"source_id": "conv_b5e6f3d3bab9", "turn_index": 1, "role": "user", "quote": "只留前两个字和后两个字，中间用***替代"}
          ],
          "unknowns": [
            "真实表头与敏感列位置需在 s1 实测确认",
            "运行环境是否具备 openpyxl 等 xlsx 读写库（首次 INSPECT 报 ModuleNotFoundError）"
          ]
        }
      }
    ],
    "issues": [
      {
        "spec": {
          "id": "u1",
          "question": "运行环境是否具备 xlsx 读写库（openpyxl 等）；若缺失，如何在不装包前提下读写 xlsx",
          "workflow_id": "conv_b5e6f3d3bab9_w1",
          "step_ids": ["s1", "s2"],
          "learning_impact": "决定 s2 采用 openpyxl 还是 zipfile+ElementTree 直接改写 xlsx XML",
          "alternatives": ["openpyxl 读写", "zipfile+ElementTree 直接改写 xlsx XML"],
          "required_evidence": ["TRY 探测可用模块并实测读取真实表结构"],
          "blocking": true,
          "status": "OPEN",
          "evidence_refs": [
            {"source_id": "conv_b5e6f3d3bab9", "turn_index": 0, "role": "user", "quote": "帮我把这份表格做一下脱敏处理"}
          ]
        }
      }
    ]
  }
}

